import React, { useState, useEffect } from 'react';
import Footer from "./Online_Ticket_system/Footer";
import { 
  Bus, 
  User, 
  ShieldCheck, 
  Mail, 
  Lock, 
  Phone, 
  Eye, 
  EyeOff, 
  ArrowRight,
  CheckCircle2,
  KeyRound,
  ArrowLeft
} from 'lucide-react';

export default function Signin({ onLoginSuccess }) {
  const [role, setRole] = useState('user'); // 'user' or 'admin'
  const [mode, setMode] = useState('signin'); // 'signin', 'signup', or 'forgot'

  const initialFormState = {
    name: '',
    emailOrPhone: '',
    phone: '',
    password: '',
    confirmPassword: '',
  };

  const [formData, setFormData] = useState(initialFormState);
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);

  // Clears all form fields completely
  const resetForm = () => {
    setFormData({
      name: '',
      emailOrPhone: '',
      phone: '',
      password: '',
      confirmPassword: '',
    });
    setError('');
    setSuccessMsg('');
    setShowPassword(false);
  };

  // Ensure form is reset on component mount
  useEffect(() => {
    resetForm();
  }, []);

  const handleRoleChange = (selectedRole) => {
    if (role !== selectedRole) {
      setRole(selectedRole);
      resetForm();
    }
  };

  const handleModeChange = (newMode) => {
    setMode(newMode);
    resetForm();
  };

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccessMsg('');

    const API_URL = 'http://localhost:5000/api/auth';

    // 1. FORGOT PASSWORD MODE
    if (mode === 'forgot') {
      if (!formData.emailOrPhone) {
        setError('Please enter your Mobile Number or Email Address.');
        return;
      }
      setSuccessMsg(`Password reset link/OTP sent to ${formData.emailOrPhone}`);
      return;
    }

    // 2. SIGN UP MODE
    if (mode === 'signup') {
      if (!formData.name || !formData.emailOrPhone || !formData.phone || !formData.password || !formData.confirmPassword) {
        setError('Please fill in all registration fields.');
        return;
      }
      if (formData.password !== formData.confirmPassword) {
        setError('Passwords do not match!');
        return;
      }
      if (formData.password.length < 6) {
        setError('Password must be at least 6 characters.');
        return;
      }

      setLoading(true);
      
      // Helper function to save new user to LocalStorage for Admin view
      const saveUserToLocalStorage = () => {
        const existingUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
        
        // Prevent duplicate user entries in LocalStorage
        const userExists = existingUsers.some(
          (u) => u.email === formData.emailOrPhone || u.phone === formData.phone
        );

        if (!userExists) {
          const newUser = {
            id: 'USR-' + Math.floor(1000 + Math.random() * 9000),
            name: formData.name,
            email: formData.emailOrPhone,
            phone: formData.phone,
            password: formData.password,
            role: role === 'admin' ? 'admin' : 'Passenger',
            joined: new Date().toISOString().split('T')[0],
            status: 'Active',
            history: [
              {
                id: 'LOG-' + Math.floor(100 + Math.random() * 900),
                type: 'Account Created',
                date: new Date().toISOString().split('T')[0],
                details: `Registered as ${role === 'admin' ? 'Admin' : 'Passenger'}`
              }
            ]
          };

          existingUsers.push(newUser);
          localStorage.setItem('app_users', JSON.stringify(existingUsers));
        }
      };

      try {
        const response = await fetch(`${API_URL}/register`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            name: formData.name,
            emailOrPhone: formData.emailOrPhone,
            phone: formData.phone,
            password: formData.password,
            role: role,
          }),
        });

        const data = await response.json();
        if (!response.ok) throw new Error(data.message || 'Registration failed.');

        // Save user persistently locally for Admin panel access
        saveUserToLocalStorage();

        resetForm();
        setMode('signin');
        setSuccessMsg('Account created successfully! Please sign in with your password.');

      } catch (err) {
        // Fallback: If backend server is unreachable, save to LocalStorage directly
        saveUserToLocalStorage();
        resetForm();
        setMode('signin');
        setSuccessMsg('Account created locally! Please sign in with your password.');
      } finally {
        setLoading(false);
      }
      return;
    }

    // 3. SIGN IN MODE
    if (mode === 'signin') {
      if (!formData.emailOrPhone || !formData.password) {
        setError('Please enter your Mobile Number or Email and Password.');
        return;
      }

      setLoading(true);
      try {
        const response = await fetch(`${API_URL}/signin`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            emailOrPhone: formData.emailOrPhone,
            password: formData.password,
            role: role,
          }),
        });

        const data = await response.json();
        if (!response.ok) throw new Error(data.message || 'Sign in failed.');

        if (data.token) {
          localStorage.setItem('token', data.token);
        }

        if (onLoginSuccess) {
          onLoginSuccess(data.user);
        }
      } catch (err) {
        // Fallback validation using LocalStorage accounts
        const existingUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
        const foundUser = existingUsers.find(
          (u) => (u.email === formData.emailOrPhone || u.phone === formData.emailOrPhone) && u.password === formData.password
        );

        if (foundUser) {
          if (onLoginSuccess) {
            onLoginSuccess({
              id: foundUser.id,
              name: foundUser.name,
              emailOrPhone: foundUser.email,
              phone: foundUser.phone,
              role: foundUser.role
            });
          }
        } else {
          setError(err.message || 'Invalid credentials.');
        }
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div style={styles.pageContainer}>
      <div style={styles.authWrapper}>

        {/* LEFT PANEL */}
        <div style={styles.leftSection}>
          <div style={styles.brandGroup}>
            <div style={styles.logoBadge}>
              <Bus size={28} color="#18181b" />
            </div>
            <div>
              <h1 style={styles.leftTitle}>ONLINE BUS</h1>
              <span style={styles.bdBadge}>BANGLADESH</span>
            </div>
          </div>

          <div style={styles.leftHeroContent}>
            <h2 style={styles.heroHeading}>Travel across Bangladesh smoothly.</h2>
            <p style={styles.heroSubtext}>
              Book AC & Non-AC bus seats across Dhaka, Chattogram, Sylhet, Cox's Bazar, and all major divisions.
            </p>

            <div style={styles.featureList}>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#a1a1aa" />
                <span>Real-time interactive seat selection</span>
              </div>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#a1a1aa" />
                <span>bKash, Nagad, Rocket & Card payments</span>
              </div>
              <div style={styles.featureItem}>
                <CheckCircle2 size={18} color="#a1a1aa" />
                <span>Instant SMS verification & E-Ticket download</span>
              </div>
            </div>
          </div>

          <div style={styles.leftFooter}>
            © {new Date().getFullYear()} Online Bus Bangladesh. All rights reserved.
          </div>
        </div>

        {/* RIGHT PANEL */}
        <div style={styles.rightSection}>
          
          {/* Role Toggle */}
          <div style={styles.roleToggle}>
            <button
              type="button"
              onClick={() => handleRoleChange('user')}
              style={{ ...styles.roleBtn, ...(role === 'user' ? styles.activeRole : {}) }}
            >
              <User size={16} /> Passenger
            </button>
            <button
              type="button"
              onClick={() => handleRoleChange('admin')}
              style={{ ...styles.roleBtn, ...(role === 'admin' ? styles.activeRole : {}) }}
            >
              <ShieldCheck size={16} /> Admin Portal
            </button>
          </div>

          {/* Form Header */}
          <div style={styles.formHeader}>
            <h2 style={styles.formTitle}>
              {mode === 'forgot' && 'Reset Password'}
              {mode === 'signup' && `Create ${role === 'admin' ? 'Admin' : 'Passenger'} Account`}
              {mode === 'signin' && `${role === 'admin' ? 'Admin' : 'Passenger'} Sign In`}
            </h2>
            <p style={styles.formSubtext}>
              {mode === 'forgot' && 'Enter your registered Email/Mobile to receive reset instructions.'}
              {mode === 'signup' && 'Fill details below to register for online bus booking.'}
              {mode === 'signin' && `Enter your ${role === 'admin' ? 'Admin credentials' : 'Mobile Number or Email'} to proceed.`}
            </p>
          </div>

          {/* Alert Messages */}
          {error && <div style={styles.errorAlert}>{error}</div>}
          {successMsg && <div style={styles.successAlert}>{successMsg}</div>}

          {/* Input Form */}
          <form onSubmit={handleSubmit} style={styles.form} method="POST">

            {/* Full Name (Sign Up Only) */}
            {mode === 'signup' && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Full Name</label>
                <div style={styles.inputWrapper}>
                  <User size={18} style={styles.inputIcon} />
                  <input
                    type="text"
                    name="name"
                    placeholder="e.g. Tanvir Hossain"
                    value={formData.name}
                    onChange={handleInputChange}
                    style={styles.input}
                    autoComplete="name"
                  />
                </div>
              </div>
            )}

            {/* Email / Mobile Field */}
            <div style={styles.inputGroup}>
              <label style={styles.label}>
                {mode === 'signup' ? 'Email Address' : 'Mobile Number or Email'}
              </label>
              <div style={styles.inputWrapper}>
                <Mail size={18} style={styles.inputIcon} />
                <input
                  type="text"
                  name="emailOrPhone"
                  placeholder={
                    mode === 'signup' 
                      ? 'passenger@example.com' 
                      : role === 'admin' 
                        ? 'admin@gmail.com' 
                        : '017XXXXXXXX or user@gmail.com'
                  }
                  value={formData.emailOrPhone}
                  onChange={handleInputChange}
                  style={styles.input}
                  autoComplete="email"
                  required
                />
              </div>
            </div>

            {/* Mobile Field (Sign Up Only) */}
            {mode === 'signup' && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Mobile Number</label>
                <div style={styles.inputWrapper}>
                  <Phone size={18} style={styles.inputIcon} />
                  <input
                    type="tel"
                    name="phone"
                    placeholder="01712345678"
                    value={formData.phone}
                    onChange={handleInputChange}
                    style={styles.input}
                    autoComplete="tel"
                  />
                </div>
              </div>
            )}

            {/* Password Field */}
            {mode !== 'forgot' && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Password</label>
                <div style={styles.inputWrapper}>
                  <Lock size={18} style={styles.inputIcon} />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    name="password"
                    placeholder="••••••••"
                    value={formData.password}
                    onChange={handleInputChange}
                    style={styles.input}
                    autoComplete={mode === 'signup' ? 'new-password' : 'current-password'}
                    required
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    style={styles.eyeBtn}
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>

                {/* Forgot Password Link Under Password Field */}
                {mode === 'signin' && (
                  <div style={styles.forgotRow}>
                    <button
                      type="button"
                      onClick={() => handleModeChange('forgot')}
                      style={styles.forgotBtn}
                    >
                      Forgot password?
                    </button>
                  </div>
                )}
              </div>
            )}

            {/* Confirm Password (Sign Up Only) */}
            {mode === 'signup' && (
              <div style={styles.inputGroup}>
                <label style={styles.label}>Confirm Password</label>
                <div style={styles.inputWrapper}>
                  <Lock size={18} style={styles.inputIcon} />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    name="confirmPassword"
                    placeholder="••••••••"
                    value={formData.confirmPassword}
                    onChange={handleInputChange}
                    style={styles.input}
                    autoComplete="new-password"
                  />
                </div>
              </div>
            )}

            {/* Submit Button */}
            <button type="submit" style={styles.submitBtn} disabled={loading}>
              {loading ? (
                <span>Connecting...</span>
              ) : (
                <>
                  {mode === 'forgot' && (
                    <>
                      <KeyRound size={18} /> Send Reset Link
                    </>
                  )}
                  {mode === 'signup' && (
                    <>
                      <span>Register Account</span> <ArrowRight size={18} />
                    </>
                  )}
                  {mode === 'signin' && (
                    <>
                      <span>Sign In as {role === 'admin' ? 'Admin' : 'Passenger'}</span> <ArrowRight size={18} />
                    </>
                  )}
                </>
              )}
            </button>
          </form>

          {/* Mode Switching Links */}
          <div style={styles.switchContainer}>
            {mode === 'forgot' ? (
              <button
                type="button"
                onClick={() => handleModeChange('signin')}
                style={styles.backBtn}
              >
                <ArrowLeft size={16} /> Back to Sign In
              </button>
            ) : (
              <>
                <span>{mode === 'signup' ? 'Already registered?' : "Don't have an account?"}</span>
                <button
                  type="button"
                  onClick={() => handleModeChange(mode === 'signup' ? 'signin' : 'signup')}
                  style={styles.switchBtn}
                >
                  {mode === 'signup' ? 'Sign In' : 'Sign Up'}
                </button>
              </>
            )}
            <footer/>
          </div>

        </div>
      </div>
    </div>
  );
}

const styles = {
  pageContainer: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#27272a',
    padding: '24px',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },
  authWrapper: {
    display: 'flex',
    width: '100%',
    maxWidth: '960px',
    minHeight: '600px',
    backgroundColor: '#ffffff',
    borderRadius: '24px',
    overflow: 'hidden',
    boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.4)',
  },
  leftSection: {
    flex: '1',
    backgroundColor: '#18181b',
    color: '#ffffff',
    padding: '48px 40px',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'space-between',
  },
  brandGroup: { display: 'flex', alignItems: 'center', gap: '12px' },
  logoBadge: {
    backgroundColor: '#ffffff',
    padding: '8px',
    borderRadius: '12px',
    display: 'flex',
  },
  leftTitle: { fontSize: '1.25rem', fontWeight: '800', letterSpacing: '1px', margin: 0, color: '#ffffff' },
  bdBadge: { fontSize: '0.65rem', fontWeight: '700', color: '#a1a1aa', letterSpacing: '2px' },
  leftHeroContent: { margin: '32px 0' },
